import {posts} from "./catalog.mjs";

// Shared validation/normalization (mirrors packages/shared/contracts.mjs semantics)
const DEFAULT_PAGE=1, DEFAULT_LIMIT=6, MIN_PAGE=1, MIN_LIMIT=1, MAX_LIMIT=50;

function toInt(value,fallback,min,max){
  const n=Number.parseInt(value,10);
  if(!Number.isFinite(n)) return fallback;
  if(n<min) return min;
  if(n>max) return max;
  return n;
}

export function normalizePostQuery(params={}){
  const raw=params&&typeof params==="object"?params:{};
  const page=toInt(raw.page,DEFAULT_PAGE,MIN_PAGE,Number.MAX_SAFE_INTEGER);
  const limit=toInt(raw.limit,DEFAULT_LIMIT,MIN_LIMIT,MAX_LIMIT);
  const q=typeof raw.q==="string"?raw.q.trim().toLowerCase():"";
  const category=typeof raw.category==="string"?raw.category.trim():"";
  return {q,category,page,limit};
}

export function listPosts(params={}){
  const query=normalizePostQuery(params);
  const filtered=posts.filter(post=>{
    if(query.category&&post.category!==query.category) return false;
    if(query.q){
      const haystack=`${post.title} ${post.excerpt} ${post.body}`.toLowerCase();
      if(!haystack.includes(query.q)) return false;
    }
    return true;
  }).sort((a,b)=>String(b.publishedAt).localeCompare(String(a.publishedAt)));
  const total=filtered.length;
  const totalPages=Math.max(1,Math.ceil(total/query.limit));
  const page=Math.min(query.page,totalPages);
  const start=(page-1)*query.limit;
  return {
    items:filtered.slice(start,start+query.limit),
    page,limit:query.limit,total,totalPages
  };
}

