import assert from "node:assert/strict";
import test from "node:test";
import {listPosts} from "./posts.mjs";
import {createServer} from "../../server.mjs";

test("case-insensitive search covers title, excerpt, and body",()=>{
  const result=listPosts({q:"PAPER"});
  assert.ok(result.items.length>0);
  assert.ok(result.items.every(post=>[post.title,post.excerpt,post.body].join(" ").toLowerCase().includes("paper")));
});

test("search matches excerpt and body, not only title",()=>{
  const byExcerpt=listPosts({q:"collective memory"});
  assert.ok(byExcerpt.items.some(post=>post.id==="p03"));
  const byBody=listPosts({q:"color stores"});
  assert.ok(byBody.items.some(post=>post.id==="p10"));
});

test("category filter and stable pagination return metadata",()=>{
  const first=listPosts({category:"Design",page:"1",limit:"2"});
  const second=listPosts({category:"Design",page:"2",limit:"2"});
  assert.equal(first.total,4);assert.equal(first.totalPages,2);assert.equal(first.items.length,2);assert.equal(second.items.length,2);
  assert.ok(first.items[0].publishedAt>=first.items[1].publishedAt);assert.notEqual(first.items[1].id,second.items[0].id);
});

test("results are sorted by publishedAt descending",()=>{
  const result=listPosts({});
  const dates=result.items.map(post=>post.publishedAt);
  const sorted=[...dates].sort((a,b)=>String(b).localeCompare(String(a)));
  assert.deepEqual(dates,sorted);
});

test("combined search and category filter intersect",()=>{
  const result=listPosts({q:"print",category:"Design"});
  assert.ok(result.items.length>0);
  assert.ok(result.items.every(post=>post.category==="Design"));
});

test("empty result set returns complete list response shape",()=>{
